$_MODULE['<{megfaq}prestashop>5cd322708044b712d9e26df9ee4587ad'] = 'This module does not add FAQPage structured data, and that is on purpose. Google stopped showing FAQ rich results on 7 May 2026 and removed the documentation for them in June. Adding the markup would not bring the boxes back. What still works is what this module does: putting the questions and answers in the page the server sends, where shoppers read them and where search engines and AI answer engines can quote them.';
$_MODULE['<{megfaq}prestashop>configure_5cd322708044b712d9e26df9ee4587ad'] = 'This module does not add FAQPage structured data, and that is on purpose. Google stopped showing FAQ rich results on 7 May 2026 and removed the documentation for them in June. Adding the markup would not bring the boxes back. What still works is what this module does: putting the questions and answers in the page the server sends, where shoppers read them and where search engines and AI answer engines can quote them.';
